function snapshot_ToyBasic()
% Self-contained snapshot generated by simulink-snapshot-edit.
% Run once to rebuild ToyBasic.slx exactly (blocks/params/positions/routing).
% Local-edit workflow: edit only the lines of the block you need.
  if bdIsLoaded('ToyBasic'), close_system('ToyBasic', 0); end
  new_system('ToyBasic');
  m = 'ToyBasic';

  % ---- solver / config / model params ----

  % ---- callbacks ----

  % ---- Model Workspace variables ----

  % ---- blocks (positions & full parameters preserved) ----
  add_block('simulink/Sources/Constant', [m '/c1'], 'Position', [40 40 80 70], 'Value', '1', 'VectorParams1D', 'on', 'OutMin', '[]', 'OutMax', '[]', 'OutDataTypeStr', 'Inherit: Inherit from ''Constant value''', 'LockScale', 'off', 'SampleTime', 'inf', 'FramePeriod', 'inf');
  add_block('simulink/Math Operations/Gain', [m '/g1'], 'Position', [140 40 200 70], 'Gain', '2', 'Multiplication', 'Element-wise(K.*u)', 'ParamMin', '[]', 'ParamMax', '[]', 'ParamDataTypeStr', 'Inherit: Inherit via internal rule', 'OutMin', '[]', 'OutMax', '[]', 'OutDataTypeStr', 'Inherit: Inherit via internal rule', 'LockScale', 'off', 'RndMeth', 'Floor', 'SaturateOnIntegerOverflow', 'off', 'SampleTime', '-1');
  add_block('simulink/Sinks/Scope', [m '/sc1'], 'Position', [260 40 310 70], 'OpenAtSimulationStart', 'off', 'DisplayFullPath', 'off', 'NumInputPorts', '1', 'LayoutDimensionsString', '[1 1]', 'SampleTime', '-1', 'FrameBasedProcessingString', 'Elements as channels (sample based)', 'MaximizeAxes', 'Off', 'AxesScaling', 'Manual', 'AxesScalingNumUpdates', '10', 'TimeSpanOverrunAction', 'Wrap', 'TimeUnits', 'None', 'TimeDisplayOffset', '0', 'TimeAxisLabels', 'Bottom displays only', 'ShowTimeAxisLabel', 'off', 'ActiveDisplayString', '1', 'Title', '%<SignalLabel>', 'ShowLegend', 'off', 'ShowGrid', 'on', 'PlotAsMagnitudePhase', 'off', 'ActiveDisplayYMinimum', '-10', 'ActiveDisplayYMaximum', '10', 'YLabel', '', 'DataLoggingLimitDataPoints', 'off', 'DataLoggingMaxPoints', '5000', 'DataLoggingDecimateData', 'off', 'DataLoggingDecimation', '2', 'DataLogging', 'off', 'DataLoggingVariableName', 'ScopeData', 'DataLoggingSaveFormat', 'Dataset');
  try, set_param(m, 'SimulationCommand', 'update'); catch, end

  % ---- lines ----
  lnH = add_line(m, 'g1/1', 'sc1/1', 'autorouting', 'off');
  try, set_param(lnH, 'Points', [205 55;255 55]); catch, end
  lnH = add_line(m, 'c1/1', 'g1/1', 'autorouting', 'off');
  try, set_param(lnH, 'Points', [85 55;135 55]); catch, end

  % ---- annotations (top level) ----

  snpDir = fileparts(mfilename('fullpath'));
  snpOut = fullfile(snpDir, '..\models');
  try, bdclose('ToyBasic_tmp_save'); catch, end
  if ~isfolder(snpOut), mkdir(snpOut); end
  if isfile(fullfile(snpOut, 'ToyBasic_tmp_save.slx')), delete(fullfile(snpOut, 'ToyBasic_tmp_save.slx')); end
  save_system(m, fullfile(snpOut, 'ToyBasic_tmp_save.slx'));
  close_system(m, 0);
  movefile(fullfile(snpOut, 'ToyBasic_tmp_save.slx'), fullfile(snpOut, 'ToyBasic.slx'), 'f');
end

